import {restoredMessage,backupMessage} from './recovery-messages.js';
import {SetupProfile} from './setup-profile.js';
import {passkeySecret} from './passkey.js';
const $=id=>document.getElementById(id),profile=new SetupProfile();let busy=false,resetRevision=null;
function note(message){$('profile-message').textContent=message}
function clearReset(){resetRevision=null;$('reset-form').hidden=true;for(const id of ['reset-password','reset-confirm'])$(id).value='';$('reset-ack').checked=false;$('reset-message').textContent=''}
async function refresh(){const record=await profile.read(),target=record;$('reset-open').disabled=!target||busy;$('reset-secret-label').textContent='Recovery key (leave empty to confirm with your passkey instead)';$('reset-password').required=false;if(!target)clearReset();$('profile-title').textContent=record?'Your vault profile is saved':'Set up QVault on this device';$('profile-description').textContent=record?'Unlock QVault from the toolbar to use your saved accounts. Keep an encrypted backup before moving to another device.':'Restore a backup file to open your existing vault on this computer.';$('profile-state').textContent=record?'PROFILE SAVED':'NO PROFILE YET';$('backup').disabled=!record;$('restore-profile').disabled=!!record;$('restore-help').textContent=record?'A profile already exists. Restore cannot overwrite it.':'Choose your QVault backup file. Unlock it afterwards with the same passkey or recovery key as before. QVault then loads your latest saved entries from the cloud.';return record}
async function work(fn){if(busy)return;busy=true;for(const id of ['reset-open','reset-submit','reset-cancel','reset-password','reset-confirm','reset-ack'])$(id).disabled=true;$('backup').disabled=true;$('restore-profile').disabled=true;try{await fn()}catch(e){note(e instanceof SyntaxError?'This file is not a valid encrypted QVault backup.':e.message)}finally{busy=false;for(const id of ['reset-submit','reset-cancel','reset-password','reset-confirm','reset-ack'])$(id).disabled=false;try{await refresh()}catch(e){note(e.message)}}}
$('backup').onclick=()=>work(async()=>{const text=await profile.backup(),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));try{const a=document.createElement('a');a.href=url;a.download='qvault-encrypted-profile-'+JSON.parse(text).profileId+'.json';a.click();note(backupMessage(JSON.parse(text)))}finally{setTimeout(()=>URL.revokeObjectURL(url),1000)}});
$('restore-profile').onchange=()=>{const file=$('restore-profile').files?.[0];if(!file)return;work(async()=>{await profile.restore(file);note(restoredMessage(await profile.read()));$('restore-profile').value=''})};
refresh().catch(e=>note(e.message));

$('reset-open').onclick=()=>work(async()=>{const record=await profile.resetTarget();if(!record)throw Error('No local profile to reset');clearReset();resetRevision=record.revision;$('reset-form').hidden=false;});
$('reset-cancel').onclick=()=>{if(!busy)clearReset()};
$('reset-form').onsubmit=e=>{e.preventDefault();if(busy)return;const request={revision:resetRevision,recoveryKey:$('reset-password').value,confirmation:$('reset-confirm').value,acknowledged:$('reset-ack').checked};$('reset-password').value='';work(async()=>{let secret=null;try{const target=await profile.resetTarget();if(target&&!request.recoveryKey){$('reset-message').textContent='Confirm with your passkey…';secret=await passkeySecret({slots:target.slots});request.secret={prf:secret.prf}}await profile.reset(request);clearReset();$('reset-details').open=false;note('Local profile removed. Open QVault to see the setup screen. QKMS keys and cloud backups were not deleted.')}catch(e){$('reset-message').textContent=e.message;throw e}finally{secret?.prf?.fill(0)}})};
